// RuntimeCapability probe() 항목: `capabilities` jsonb 원소. **contracts/protocol.go `Capability`와 키가 1:1**(v0.4.1, PR #26 대조표 — 이전 transport[]·usage_reporting·options는 protocol.go에 없어 채워지지 않았다). 데몬 → 서버 → 웹이 같은 모양을 쓴다(harness.md §9).
type RuntimeCapability struct {
	// AdapterVersion ACP 어댑터 실측 버전. 실측 실패 시 null(핀 상수로 채우지 않는다).
	AdapterVersion nullable.Nullable[string] `json:"adapter_version,omitempty"`

	// AllowOnceMissing 권한 협상에서 allow_once 부재 3회 누적(E12-03)
	AllowOnceMissing *bool `json:"allow_once_missing,omitempty"`

	// BriefTransport 브리프 전달 경로(harness §1). 값이 없으면 필드를 생략하거나 null — enum에 null을 넣지 않는다(생성기가 상수 '<nil>'을 만든다, v0.4.2).
	BriefTransport nullable.Nullable[RuntimeCapabilityBriefTransport] `json:"brief_transport,omitempty"`

	// Kind `runtime_kind` (FR-1.6)
	Kind     RuntimeKind `json:"kind"`
	LoggedIn bool        `json:"logged_in"`
	Models   *[]string   `json:"models,omitempty"`

	// ProtocolVersion ACP initialize 응답. v1은 1.
	ProtocolVersion nullable.Nullable[int] `json:"protocol_version,omitempty"`

	// Resume session/load 지원 — harness §6
	Resume *bool `json:"resume,omitempty"`

	// SupportedOptions 이 런타임이 받는 프로파일 옵션과 허용 값(v0.5). 예 `{effort: [low, medium, high, xhigh]}`. PRD §8.2.6 "세션이 광고한 능력 범위 내에서만"의 그 광고다 — v0.4.1 에서 protocol.go 대조 중 빠졌는데, createProfile 의 422 규칙과 S10 의 "미지원 옵션 비활성 + 사유"(SCREEN §4.7)가 둘 다 이 값을 전제한다. 데몬이 (kind, adapter_version) 으로 아는 범위를 채운다. **키가 없거나 비어 있으면 "광고 없음"** — 웹은 옵션 편집을 비활성으로 두고 사유를 보이며, 서버는 어떤 옵션 값도 받지 않는다(빈 광고 = 허용 없음).
	SupportedOptions *map[string][]string `json:"supported_options,omitempty"`

	// ToolDisallow 툴 차단 수단 존재(harness §3)
	ToolDisallow *bool `json:"tool_disallow,omitempty"`

	// ToolSurface 에이전트가 플랫폼에 말하는 수단(harness §10 v0.8). `mcp` = session/new.mcpServers 를 존중(claude_code). `cli_wrapper` = MCP 를 무시하는 런타임(hermes) — 데몬이 attempt 별 래퍼 실행 파일을 만들고 브리프에 절대 경로를 적는다. 판정은 initialize 응답의 mcpCapabilities 유무. 값이 없으면 필드 생략.
	ToolSurface nullable.Nullable[RuntimeCapabilityToolSurface] `json:"tool_surface,omitempty"`

	// Usage 사용량 보고 여부. false면 비용은 추정 배지(FR-7.3)
	Usage *bool `json:"usage,omitempty"`

	// UsageMidturn harness v0.8.5 §9 — 런타임(+어댑터 설정)이 턴 중 usage 를 주는가. false 면 턴 중 예산 강제는 finish 사후(E9-10)로만.
	UsageMidturn *bool `json:"usage_midturn,omitempty"`

	// Version 런타임 CLI 버전(예 Claude Code 2.1.258, Hermes 0.20.6).
	Version nullable.Nullable[string] `json:"version,omitempty"`
}

// RuntimeCapabilityBriefTransport 브리프 전달 경로(harness §1). 값이 없으면 필드를 생략하거나 null — enum에 null을 넣지 않는다(생성기가 상수 '<nil>'을 만든다, v0.4.2).
type RuntimeCapabilityBriefTransport string

// RuntimeCapabilityToolSurface 에이전트가 플랫폼에 말하는 수단(harness §10 v0.8). `mcp` = session/new.mcpServers 를 존중(claude_code). `cli_wrapper` = MCP 를 무시하는 런타임(hermes) — 데몬이 attempt 별 래퍼 실행 파일을 만들고 브리프에 절대 경로를 적는다. 판정은 initialize 응답의 mcpCapabilities 유무. 값이 없으면 필드 생략.
